<section class="content-header"><h1><i class="fa fa-bus"></i> Reporte por viaje</h1><div class="no-print" style="margin-top:8px"><a class="btn btn-info btn-sm" href="<?php echo site_url('reporte_transporte/ventas_fecha'); ?>"><i class="fa fa-bar-chart"></i> Ventas por fecha</a></div></section><section class="content">
